fn solve(r1: i8, c1: i8, r2: i8, c2: i8) -> Vec<i8> {
    // Rook moves
    let rook = if r1 == r2 && c1 == c2 {
        0
    } else if r1 == r2 || c1 == c2 {
        1
    } else {
        2
    };

    // Bishop moves
    let bishop = if r1 == r2 && c1 == c2 {
        // same square
        0
    } else if (r1 - r2).abs() == (c1 - c2).abs() {
        // same diagonal
        1
    } else if (r1 + c1) % 2 == (r2 + c2) % 2 {
        // same color but not diagonal
        2
    } else {
        // different colors, unreachable
        0
    };

    // King moves = Chebyshev distance
    let row_diff = (r1 - r2).abs();
    let col_diff = (c1 - c2).abs();
    let king = row_diff.max(col_diff);

    vec![rook, bishop, king]
}

